--
-- Table structure for table `pension_calculate_result`
--

DROP TABLE IF EXISTS `pension_calculate_result`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pension_calculate_result` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `openid` varchar(128) DEFAULT NULL COMMENT '微信openid',
  `title` varchar(128) NOT NULL DEFAULT '养老金待遇测算' COMMENT '测算标题',
  `monthly_pension` decimal(12,2) DEFAULT NULL COMMENT '月养老金',
  `batch_no` varchar(32) NOT NULL,
  `calculate_no` varchar(32) NOT NULL,
  `name` varchar(32) DEFAULT NULL,
  `id_card` varchar(18) DEFAULT NULL,
  `gender` varchar(4) DEFAULT NULL,
  `birth_date` varchar(10) DEFAULT NULL,
  `personal_info_json` text,
  `retirement_identity` varchar(16) NOT NULL,
  `retirement_age` int NOT NULL,
  `retirement_year` int NOT NULL,
  `actual_payment_years` decimal(4,1) NOT NULL,
  `visual_payment_years` decimal(4,1) DEFAULT '0.0',
  `total_payment_years` decimal(4,1) NOT NULL,
  `average_payment_index` decimal(8,4) NOT NULL,
  `personal_account_amount` decimal(12,2) DEFAULT NULL,
  `payment_years` decimal(6,2) DEFAULT NULL COMMENT '缴费年限',
  `payment_months` int DEFAULT NULL COMMENT '计发月数或缴费月数',
  `retire_age` int DEFAULT NULL COMMENT '退休年龄',
  `request_json` json DEFAULT NULL COMMENT '原始请求JSON',
  `result_json` json DEFAULT NULL COMMENT '测算结果JSON',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `calculation_params_json` text,
  `basic_pension` decimal(10,2) NOT NULL,
  `personal_account_pension` decimal(10,2) NOT NULL,
  `transitional_pension` decimal(10,2) DEFAULT '0.00',
  `payment_years_pension` decimal(10,2) DEFAULT '0.00',
  `total_monthly_pension` decimal(10,2) NOT NULL,
  `calculation_process` text,
  `warnings` text,
  `calculate_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `calculate_version` varchar(16) DEFAULT 'V1.0',
  `social_avg_wage_year` int NOT NULL,
  `is_shared` tinyint DEFAULT '0',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_calculate_no` (`calculate_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_calculate_time` (`calculate_time` DESC),
  KEY `idx_user_created` (`user_id`,`created_at`),
  KEY `idx_openid_created` (`openid`,`created_at`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

